#[derive(Clone, Copy, Serialize)]
enum FunderBlockingRule {
    ExactName,
    ExactPresentAddress,
    ThreeUnicodeCharacters,
    InitialAndFinalAsciiWordPrefix,
    SharedDomainKey,
}
#[derive(Serialize)]
struct NativeProvenance<'a> {
    engine: &'static str, // weldrs
    engine_version: &'static str, // 0.2.2
    distance: Utf8ByteSimd,
    calibrated: bool, // false
    model: &'a FrozenFunderModel,
}
#[derive(Serialize)]
struct Utf8ByteSimd;

// Ord agrees with the profile's lexicographic key order.
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct ProfileIndex(usize);
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Candidate { left: ProfileIndex, right: ProfileIndex }
struct BoundedCandidates { pairs: BTreeSet<Candidate>, budget: usize }
impl BoundedCandidates {
